#!/usr/bin/env python3
"""Disordered-structure model generated by the discus-python Structure Builder.

What this script does
  1. Builds a disordered supercell from the model below (site occupancies, molecules in
     preferred orientations, correlated occupancies, rigid-body and atomic displacements).
  2. Optionally runs DISCUS Monte Carlo (mmc) on atom-only models.
  3. Writes the supercell as a DISCUS .stru (plus .xyz and a summary).
  4. Runs DISCUS 6.23.01 to compute
       - 3D diffuse scattering (Bragg subtracted, ``set aver``) and the 3D-ΔPDF,
       - optionally the total 3D scattering and its 3D-PDF (Patterson),
       - the 1D powder PDF G(r).

Requirements: Python >= 3.10, numpy, matplotlib, h5py and discus-python
(``pip install "git+https://github.com/jmsweng/discus-python#egg=discuspdf[data]"``);
DISCUS_SUITE 6.23.01 for the calculations.

Usage
  python model.py                     # build the structure and run every enabled calculation
  python model.py --dry-run           # build and stage all DISCUS inputs, do not start DISCUS
  python model.py --numpy-preview     # also compute a quick diffuse plane with numpy (no DISCUS)
  python model.py --launcher "wsl.exe -d Ubuntu-22.04 -- bash -lc 'discus_suite -noautorun -macro run.mac'" ...
  python model.py --out results_dir --seed 7

The model itself is the JSON block CONFIG below; edit it or re-import it into the web page.
"""
from __future__ import annotations

import argparse
import json
import math
import os
import shlex
import subprocess
import sys
import warnings
from datetime import datetime, timezone
from pathlib import Path

import numpy as np

CONFIG_JSON = r"""__CONFIG__"""

VOID = "VOID"          # DISCUS's non-scattering atom type; pads cells so every cell has the same atom count
ENGINE_VERSION = "1.0"


# ---------------------------------------------------------------------------------------------
# configuration
# ---------------------------------------------------------------------------------------------
def load_config(path: str | None) -> dict:
    if path:
        return json.loads(Path(path).read_text(encoding="utf-8"))
    if CONFIG_JSON.strip() == "__CONFIG__":
        sys.exit("No model: this is the template. Run the generated script, or pass --config model.json")
    return json.loads(CONFIG_JSON)


def lattice_matrix(cell: dict) -> np.ndarray:
    """Rows a, b, c in the discuspdf canonical orientation (a ∥ x, b in the xy plane)."""
    from discuspdf import Lattice
    return Lattice.from_parameters(cell["a"], cell["b"], cell["c"],
                                   cell["alpha"], cell["beta"], cell["gamma"]).matrix


def _check_rotation(R: np.ndarray, where: str) -> np.ndarray:
    R = np.asarray(R, float).reshape(3, 3)
    if not np.allclose(R @ R.T, np.eye(3), atol=1e-6):
        raise ValueError(f"{where}: matrix is not orthogonal")
    return R


def orientation_table(cfg: dict) -> dict:
    """group id -> (molecule name, list of (R, weight)) with weights normalised to 1."""
    out = {}
    for gid, g in cfg.get("orientations", {}).items():
        mats = [_check_rotation(m, f"orientation group {gid!r}") for m in g["matrices"]]
        w = np.asarray(g.get("weights") or [1.0] * len(mats), float)
        if len(w) != len(mats) or np.any(w < 0) or w.sum() <= 0:
            raise ValueError(f"orientation group {gid!r}: bad weights")
        out[gid] = (g["molecule"], mats, w / w.sum())
    return out


def molecule_local_coords(mol: dict) -> tuple[list[str], np.ndarray]:
    """Species and Cartesian coordinates (Å) relative to the molecule's anchor."""
    species = [a["el"] for a in mol["atoms"]]
    xyz = np.array([a["xyz"] for a in mol["atoms"]], float).reshape(-1, 3)
    anchor = mol.get("anchor", "centroid")
    if anchor == "centroid":
        origin = xyz.mean(axis=0)
    elif anchor == "com":
        m = np.array([_mass(s) for s in species])
        origin = (xyz * m[:, None]).sum(axis=0) / m.sum()
    elif isinstance(anchor, int):
        origin = xyz[anchor]
    else:
        raise ValueError(f"molecule anchor {anchor!r} not understood")
    return species, xyz - origin


def _chem(sp: str) -> str | None:
    """Element of an atom name, read the way DISCUS reads it: D (deuterium) counts as H; any other name is the
    element its first two, or else first, letters spell (Ni62 -> Ni, C1 -> C, FE3+ -> Fe). Same as the page."""
    from discuspdf._elements import _ELEMENTS
    up = str(sp or "").strip().upper()
    if up in ("D", "D1-"):
        return "H"
    for t in (up[:2], up[:1]):
        s = t[:1] + t[1:].lower()
        if s in _ELEMENTS:
            return s
    return None


def _z(sp: str) -> int:
    from discuspdf._elements import _ELEMENTS
    e = _chem(sp)
    if e is None:
        raise ValueError(f"atom name {sp!r} is not an element and does not start with one")
    return _ELEMENTS[e]


def _mass_number(sp: str) -> int | None:
    """Mass number written after the element (Ni62, O18, Li7); D is 2. Labels such as C1 or Fe2 are not isotopes."""
    import re
    up = str(sp or "").strip().upper()
    if up in ("D", "D1-"):
        return 2
    m = re.fullmatch(r"[A-Za-z]{1,2}(\d{1,3})", str(sp).strip())
    z = _z(sp) if _chem(sp) else 0
    if not m or z <= 1:
        return None
    a = int(m.group(1))
    return a if 2 * z - 1 <= a <= 3 * z + 20 else None


def _mass(symbol: str) -> float:
    a = _mass_number(symbol)
    if a:
        return 2.014 if a == 2 and _chem(symbol) == "H" else float(a)
    z = _z(symbol)
    return 1.008 if z == 1 else 2.0 * z + (0.5 if z > 20 else 0.0)   # rough masses for centre of mass only


# ---------------------------------------------------------------------------------------------
# occupant draw and correlated occupancies
# ---------------------------------------------------------------------------------------------
def site_rotation(site: dict, A: np.ndarray) -> np.ndarray | None:
    """Cartesian matrix of the rotation part of a site's symmetry operation (Jones symbol, e.g. "-y,x,z+1/2")."""
    import re
    sym = site.get("sym")
    if not sym:
        return None
    M = np.zeros((3, 3))
    parts = sym.replace(" ", "").lower().split(",")
    if len(parts) != 3:
        raise ValueError(f"site {site['label']}: cannot read the operation {sym!r}")
    for i, part in enumerate(parts):
        for sign, coef, var in re.findall(r"([+-]?)(\d*\.?\d*(?:/\d+)?)\*?([xyz])", part):
            c = 1.0 if coef == "" else (float(coef.split("/")[0] or 1) / float(coef.split("/")[1]) if "/" in coef else float(coef))
            M[i, "xyz".index(var)] += -c if sign == "-" else c
    At = A.T
    R = At @ M @ np.linalg.inv(At)
    if not np.allclose(R @ R.T, np.eye(3), atol=1e-5):
        raise ValueError(f"site {site['label']}: the operation {sym} does not fit this cell")
    return R


def occupant_classes(site: dict, orient: dict, A: np.ndarray | None = None) -> list[dict]:
    """Expand a site's occupants into choice classes: atoms, single molecule orientations, vacancies."""
    classes = []
    for occ in site["occupants"]:
        p = float(occ["p"])
        if p < 0:
            raise ValueError(f"site {site['label']}: negative probability")
        if p == 0:
            continue
        # per-occupant disorder overrides (None: use the defaults of the Disorder step)
        over = {k: (None if occ.get(k) in (None, "") else float(occ[k])) for k in ("sigma", "trans", "lib")}
        if occ["type"] == "atom":
            classes.append({"type": "atom", "species": occ["species"], "p": p,
                            "b": occ.get("b"), "key": f"atom:{occ['species']}", **over})
        elif occ["type"] == "vacancy":
            classes.append({"type": "vacancy", "p": p, "key": "vacancy"})
        elif occ["type"] == "molecule":
            mol, mats, w = orient[occ["group"]]
            SR = site_rotation(site, A) if A is not None else None   # symmetry-equivalent site: rotate the molecule
            for k, (R, wk) in enumerate(zip(mats, w)):
                if wk > 0:
                    classes.append({"type": "molecule", "molecule": mol, "R": R if SR is None else SR @ R, "p": p * wk,
                                    "b": occ.get("b"), "key": f"mol:{occ['group']}:{k}",
                                    "group": occ["group"], "index": k, **over})
        else:
            raise ValueError(f"unknown occupant type {occ['type']!r}")
    total = sum(c["p"] for c in classes)
    if not classes or abs(total - 1.0) > 1e-6:
        raise ValueError(f"site {site['label']}: occupant probabilities sum to {total:.6g}, not 1")
    return classes


def draw_occupants(cfg: dict, classes: list[list[dict]], n: tuple, rng) -> np.ndarray:
    """choice[s, ix, iy, iz] = index into classes[s]."""
    n_sites = len(classes)
    choice = np.zeros((n_sites, *n), dtype=np.int64)
    n_cells = int(np.prod(n))
    for s, site in enumerate(cfg["sites"]):
        p = np.array([c["p"] for c in classes[s]])
        if site.get("draw", "random") == "exact":
            counts = np.floor(p * n_cells).astype(int)
            rest = n_cells - counts.sum()
            if rest:   # largest remainders, ties broken at random
                frac = p * n_cells - counts + rng.random(len(p)) * 1e-9
                counts[np.argsort(-frac)[:rest]] += 1
            labels = np.repeat(np.arange(len(p)), counts)
            rng.shuffle(labels)
            choice[s] = labels.reshape(n[2], n[1], n[0]).transpose(2, 1, 0)
        else:
            choice[s] = rng.choice(len(p), size=n_cells, p=p).reshape(n[2], n[1], n[0]).transpose(2, 1, 0)
    return choice


def _rule_hits(r: str, sp: str) -> bool:
    """A contact rule names an atom name or an element: 'Ni' covers Ni and Ni62, 'H' covers H and D."""
    return r == "any" or str(r).upper() == str(sp).upper() or r == _chem(sp)


def contact_model(cfg: dict, classes, A: np.ndarray, mols: dict) -> dict:
    """Penalty and contact-count tables for every pair of neighbouring site positions (ideal atom positions,
    no translation / libration / displacement noise). Same construction as the web page."""
    con = cfg.get("disorder", {}).get("contacts") or {}
    rules = [(r["a"], r["b"], float(r["dmin"]) ** 2, float(r["penalty"])) for r in con.get("rules", [])
             if float(r.get("dmin", 0)) > 0 and float(r.get("penalty", 0)) > 0]
    sites = cfg["sites"]
    entries = [[] for _ in sites]
    pairs = []
    if not con.get("enabled") or not rules:
        return {"entries": entries, "pairs": pairs, "rules": rules}

    def shape(c):
        if c["type"] == "atom":
            return [c["species"]], np.zeros((1, 3))
        if c["type"] == "molecule":
            sp, loc = mols[c["molecule"]]
            return sp, loc @ np.asarray(c["R"]).T
        return [], np.zeros((0, 3))

    shapes = [[shape(c) for c in cl] for cl in classes]
    R = [max([0.0] + [float(np.linalg.norm(p, axis=1).max()) for _, p in sh if len(p)]) for sh in shapes]
    dmax = math.sqrt(max(r[2] for r in rules))
    recip = np.linalg.norm(np.linalg.inv(A), axis=0)
    match = lambda r, e1, e2: (_rule_hits(r[0], e1) and _rule_hits(r[1], e2)) or (_rule_hits(r[0], e2) and _rule_hits(r[1], e1))
    for i, s1 in enumerate(sites):
        for j, s2 in enumerate(sites):
            cut = R[i] + R[j] + dmax
            m = [int(math.ceil(cut * r)) + 1 for r in recip]
            for tx in range(-m[0], m[0] + 1):
                for ty in range(-m[1], m[1] + 1):
                    for tz in range(-m[2], m[2] + 1):
                        if i == j and not (tx or ty or tz):
                            continue
                        off = (np.array([tx, ty, tz], float) + np.asarray(s2["frac"], float) - np.asarray(s1["frac"], float)) @ A
                        dist = float(np.linalg.norm(off))
                        if dist > cut + 1e-9:
                            continue
                        K, L = len(classes[i]), len(classes[j])
                        table = np.zeros((K, L))
                        count = np.zeros((K, L), dtype=np.int64)
                        for k in range(K):
                            ea, pa = shapes[i][k]
                            for l in range(L):
                                eb, pb = shapes[j][l]
                                if not len(pa) or not len(pb):
                                    continue
                                d2 = (((off + pb)[None, :, :] - pa[:, None, :]) ** 2).sum(axis=2)
                                e = 0.0
                                hits = np.zeros(d2.shape, dtype=bool)
                                for r in rules:
                                    mk = np.array([[match(r, ea[u], eb[v]) for v in range(len(eb))] for u in range(len(ea))])
                                    h = mk & (d2 < r[2])
                                    e += r[3] * int(h.sum())
                                    hits |= h
                                table[k, l] = e
                                count[k, l] = int(hits.sum())
                        if table.any():
                            entries[i].append({"o": j, "t": (tx, ty, tz), "table": table, "count": count})
                            if i <= j:
                                pairs.append({"i": i, "j": j, "t": (tx, ty, tz), "dist": dist,
                                              "n_forbidden_pairs": int((table > 0).sum()), "n_pairs": int(table.size)})
    return {"entries": entries, "pairs": pairs, "rules": rules}


def ordering_mc(cfg: dict, classes, choice: np.ndarray, A: np.ndarray, mols: dict, rng, log) -> dict:
    """Monte Carlo on the occupant choices (same model as the web page):
    - neighbour energies J added when two listed neighbours hold the same occupant (Correlated occupants), and
    - contact penalties for atom pairs of neighbouring occupants closer than a rule's minimum distance
      (Forbidden contacts).
    Moves: swaps of occupants between cells of one site (composition kept) and, with contacts, a new orientation
    drawn with the weights from the same molecule group (change = "orientation") or from every molecule of the
    site (change = "group"); change = "none" keeps swaps only. Metropolis acceptance; optional annealing from
    10 kT down to kT over the first 60 % of the sweeps."""
    dis = cfg.get("disorder", {})
    corr = dis.get("correlations") or {}
    con = dis.get("contacts") or {}
    potts = [i for i in corr.get("interactions", []) if float(i.get("J", 0.0)) != 0.0] if corr.get("enabled") else []
    cm = contact_model(cfg, classes, A, mols)
    use_contacts = bool(cm["pairs"])
    if not potts and not use_contacts:
        return {}
    n = choice.shape[1:]
    nx, ny, nz = (int(x) for x in n)
    ncell = nx * ny * nz
    flat = [list(choice[s].transpose(2, 1, 0).ravel()) for s in range(len(classes))]   # cell = x + nx (y + ny z)
    by_group = corr.get("match") == "group"
    ids: dict = {}
    key = [[ids.setdefault(c.get("group", c["key"]) if by_group else c["key"], len(ids)) for c in cl] for cl in classes]
    change = con.get("change") or ("none" if con.get("reorient") is False else "orientation")
    # occupants a run may turn into each other: orientations of one group, or every molecule of the site
    fam = [[(("mol" if change == "group" else "mol:" + c["group"]) if c["type"] == "molecule" else c["key"]) for c in cl]
           for cl in classes]
    maps: dict = {}

    def map_of(t):
        t = tuple(int(x) for x in t)
        if t not in maps:
            x = np.arange(nx)[None, None, :]
            y = np.arange(ny)[None, :, None]
            z = np.arange(nz)[:, None, None]
            idx = ((x + t[0]) % nx) + nx * (((y + t[1]) % ny) + ny * ((z + t[2]) % nz))
            maps[t] = list(np.broadcast_to(idx, (nz, ny, nx)).ravel())
        return maps[t]

    nb = [[] for _ in classes]
    for it in potts:
        a, b, t, J = int(it["site_a"]), int(it["site_b"]), [int(x) for x in it["t"]], float(it["J"])
        nb[a].append((b, map_of(t), J, None))
        nb[b].append((a, map_of([-x for x in t]), J, None))
    for i, lst in enumerate(cm["entries"]):
        for e in lst:
            nb[i].append((e["o"], map_of(e["t"]), 0.0, e["table"].tolist()))

    def term(s, e, k, k2):
        o, _, J, table = e
        if table is not None:
            return table[k][k2]
        return J if key[s][k] == key[o][k2] else 0.0

    def local(s, c, k, excl):
        E = 0.0
        for e in nb[s]:
            c2 = e[1][c]
            if e[0] == s and c2 == excl:
                continue
            E += term(s, e, k, flat[e[0]][c2])
        return E

    def bond(s, c1, k1, c2, k2):
        return sum(term(s, e, k1, k2) for e in nb[s] if e[0] == s and e[1][c1] == c2)

    def measure():
        out = []
        for it in potts:
            a, b, mp = int(it["site_a"]), int(it["site_b"]), map_of(it["t"])
            out.append(sum(key[a][flat[a][c]] == key[b][flat[b][mp[c]]] for c in range(ncell)) / ncell)
        return out

    def n_contacts():
        tot = 0
        for i, lst in enumerate(cm["entries"]):
            for e in lst:
                mp, cnt = map_of(e["t"]), e["count"]
                tot += int(sum(cnt[flat[i][c], flat[e["o"]][mp[c]]] for c in range(ncell)))
        return tot // 2

    before, c_before = measure(), (n_contacts() if use_contacts else 0)
    kT = float(corr.get("kT", 1.0))
    sweeps = int(corr.get("sweeps", 50))
    reorient = use_contacts and change != "none"
    anneal = use_contacts and con.get("anneal", True)
    fam_idx = []
    for s, cl in enumerate(classes):
        g: dict = {}
        for k in range(len(cl)):
            g.setdefault(fam[s][k], []).append(k)
        fam_idx.append([g[fam[s][k]] for k in range(len(cl))])
    rnd = rng.random
    for sw in range(sweeps):
        T = kT * 10 ** max(0.0, 1 - sw / max(1.0, 0.6 * sweeps)) if anneal else kT
        for s, cls in enumerate(classes):
            if not nb[s] or len(cls) < 2:
                continue
            fl = flat[s]
            for _ in range(ncell):
                if reorient:
                    c = int(rnd() * ncell)
                    x = fl[c]
                    opts = fam_idx[s][x]
                    if len(opts) > 1:
                        u = rnd() * sum(cls[k]["p"] for k in opts)
                        y = opts[0]
                        for k in opts:
                            u -= cls[k]["p"]
                            if u <= 0:
                                y = k
                                break
                        if y != x:
                            dE = local(s, c, y, -1) - local(s, c, x, -1)
                            if dE <= 0 or rnd() < math.exp(-dE / T):
                                fl[c] = y
                c1, c2 = int(rnd() * ncell), int(rnd() * ncell)
                x1, x2 = fl[c1], fl[c2]
                if c1 == c2 or (fam[s][x1] == fam[s][x2] and (reorient or key[s][x1] == key[s][x2])):
                    continue
                if not use_contacts and key[s][x1] == key[s][x2]:
                    continue
                e0 = local(s, c1, x1, c2) + local(s, c2, x2, c1) + bond(s, c1, x1, c2, x2)
                fl[c1], fl[c2] = x2, x1
                dE = local(s, c1, x2, c2) + local(s, c2, x1, c1) + bond(s, c1, x2, c2, x1) - e0
                if not (dE <= 0 or rnd() < math.exp(-dE / T)):
                    fl[c1], fl[c2] = x1, x2
    for s in range(len(classes)):
        choice[s] = np.array(flat[s]).reshape(nz, ny, nx).transpose(2, 1, 0)
    after = measure()
    report = {"sweeps": sweeps, "kT": kT, "interactions": potts,
              "fraction_same_before": before, "fraction_same_after": after}
    for it, b0, b1 in zip(potts, before, after):
        log(f"  correlation site {it['site_a']}→{it['site_b']} t={tuple(it['t'])} J={it['J']}: "
            f"P(same) {b0:.3f} → {b1:.3f}")
    if use_contacts:
        c_after = n_contacts()
        report["contacts"] = {"rules": [{"a": r[0], "b": r[1], "dmin": math.sqrt(r[2]), "penalty": r[3]} for r in cm["rules"]],
                              "neighbour_pairs": cm["pairs"], "before": c_before, "after": c_after,
                              "change": change, "anneal": anneal}
        log(f"  forbidden contacts (ideal positions): {c_before} → {c_after} over {len(cm['pairs'])} neighbour vectors")
        for s, cl in enumerate(classes):
            h = np.bincount(np.asarray(flat[s]), minlength=len(cl)) / ncell
            groups: dict = {}
            for k, c in enumerate(cl):
                groups[c.get("group", c["key"])] = groups.get(c.get("group", c["key"]), 0.0) + h[k]
            log(f"  site {cfg['sites'][s]['label']}: " + ", ".join(f"{g} {v:.3f}" for g, v in groups.items()))
    return report


# ---------------------------------------------------------------------------------------------
# small random rotations (librations)
# ---------------------------------------------------------------------------------------------
def random_small_rotation(rng, sigma_deg: float) -> np.ndarray:
    if sigma_deg <= 0:
        return np.eye(3)
    axis = rng.normal(size=3)
    axis /= np.linalg.norm(axis)
    ang = math.radians(rng.normal(scale=sigma_deg))
    K = np.array([[0, -axis[2], axis[1]], [axis[2], 0, -axis[0]], [-axis[1], axis[0], 0]])
    return np.eye(3) + math.sin(ang) * K + (1 - math.cos(ang)) * K @ K


# ---------------------------------------------------------------------------------------------
# build the supercell
# ---------------------------------------------------------------------------------------------
def build_structure(cfg: dict, seed: int, log):
    from discuspdf import Lattice, Structure

    rng = np.random.default_rng(seed)
    cell = cfg["cell"]
    n = tuple(int(x) for x in cfg["supercell"])
    A = lattice_matrix(cell)                       # rows a, b, c (Å)
    Ainv = np.linalg.inv(A)
    orient = orientation_table(cfg)
    mols = {name: molecule_local_coords(m) for name, m in cfg.get("molecules", {}).items()}
    classes = [occupant_classes(site, orient, A) for site in cfg["sites"]]

    # slots per site = largest number of atoms any occupant needs
    def n_atoms_of(c):
        return len(mols[c["molecule"]][0]) if c["type"] == "molecule" else (1 if c["type"] == "atom" else 0)
    slots = [max(1, max(n_atoms_of(c) for c in cl)) for cl in classes]
    # where padding VOIDs go: the atoms of the site's largest occupant, so slots keep their usual place
    pad_local = []
    for cl in classes:
        big = max(cl, key=n_atoms_of)
        if big["type"] == "molecule":
            pad_local.append(mols[big["molecule"]][1] @ big["R"].T)
        else:
            pad_local.append(np.zeros((1, 3)))
    m = int(sum(slots))

    choice = draw_occupants(cfg, classes, n, rng)
    corr_report = ordering_mc(cfg, classes, choice, A, mols, rng, log)

    dis = cfg.get("disorder", {})
    rigid = dis.get("molecule_rigid", {}) or {}
    t_sigma = float(rigid.get("translation_sigma", 0.0))
    lib_sigma = float(rigid.get("libration_sigma_deg", 0.0))
    use_b = bool(cfg.get("calc", {}).get("debye_waller", False))

    N = m * int(np.prod(n))
    species = np.empty(N, dtype=object)
    cart = np.zeros((N, 3))
    cell_index = np.zeros((N, 3), dtype=np.int64)
    site_label = np.empty(N, dtype=object)
    b_iso = np.ones(N)
    molecule_id = np.full(N, -1, dtype=np.int64)    # which molecule an atom belongs to (-1: none)
    is_void = np.zeros(N, dtype=bool)
    sigma_row = np.full(N, np.nan)                  # per-occupant displacement σ (NaN: species default)

    row = 0
    mol_counter = 0
    stats = {}
    for iz in range(n[2]):                      # DISCUS cell-major order: x fastest
        for iy in range(n[1]):
            for ix in range(n[0]):
                origin = np.array([ix, iy, iz], float)
                for s, site in enumerate(cfg["sites"]):
                    c = classes[s][choice[s, ix, iy, iz]]
                    stats.setdefault(site["label"], {}).setdefault(c["key"], 0)
                    stats[site["label"]][c["key"]] += 1
                    centre = (origin + np.asarray(site["frac"], float)) @ A
                    b_site = float(site.get("b_iso", 1.0))
                    if c["type"] == "atom":
                        sp, pos = [c["species"]], centre[None, :]
                        bs = [float(c["b"]) if c.get("b") is not None else b_site]
                    elif c["type"] == "molecule":
                        msp, local = mols[c["molecule"]]
                        lib = lib_sigma if c.get("lib") is None else c["lib"]
                        trans = t_sigma if c.get("trans") is None else c["trans"]
                        R = c["R"] @ random_small_rotation(rng, lib)
                        shift = rng.normal(scale=trans, size=3) if trans > 0 else 0.0
                        sp, pos = msp, centre + shift + local @ R.T
                        bs = [float(c["b"]) if c.get("b") is not None else b_site] * len(msp)
                    else:
                        sp, pos, bs = [], np.zeros((0, 3)), []
                    k = len(sp)
                    for j in range(slots[s]):
                        r = row + j
                        cell_index[r] = (ix, iy, iz)
                        site_label[r] = f"{site['label'][:10]}.{j}"
                        if j < k:
                            species[r] = sp[j]
                            cart[r] = pos[j]
                            b_iso[r] = bs[j]
                            if c.get("sigma") is not None:
                                sigma_row[r] = c["sigma"]
                            if c["type"] == "molecule":
                                molecule_id[r] = mol_counter
                        else:
                            species[r] = VOID
                            cart[r] = centre + pad_local[s][j]
                            is_void[r] = True
                    if c["type"] == "molecule":
                        mol_counter += 1
                    row += slots[s]

    # static Gaussian displacements: per-occupant σ where given, else the species default
    sig = {k: float(v) for k, v in (dis.get("atomic_displacements", {}) or {}).items()}
    sigma = np.array([sig.get(s, 0.0) for s in species])
    sigma = np.where(np.isfinite(sigma_row), sigma_row, sigma)
    sigma[is_void] = 0.0
    if np.any(sigma < 0):
        raise ValueError("displacement σ must be >= 0")
    move = sigma > 0
    cart[move] += rng.normal(size=(int(move.sum()), 3)) * sigma[move, None]

    frac_unit = cart @ Ainv                           # unit-cell fractions
    if cfg.get("wrap", False):   # off by default: DISCUS lists atoms by cell, molecules stay whole
        frac_unit = np.mod(frac_unit, np.array(n, float))
    frac_super = frac_unit / np.array(n, float)
    if not use_b:
        b_iso[:] = 1.0                                 # written but not used (temp ignore)
    if np.any(b_iso[~is_void] < 0.001):
        raise ValueError("DISCUS 6.23.01 replaces B < 0.001 by 1.0; use B >= 0.001 or switch Debye–Waller off")

    super_lat = Lattice.from_parameters(cell["a"] * n[0], cell["b"] * n[1], cell["c"] * n[2],
                                        cell["alpha"], cell["beta"], cell["gamma"])
    structure = Structure(super_lat, species, frac_super, model="configuration", site_label=site_label,
                          cell_index=cell_index, supercell=n, b_iso=b_iso, min_separation=None)
    info = {"atoms_per_cell": m, "slots_per_site": slots, "n_rows": N, "n_void": int(is_void.sum()),
            "n_molecules": mol_counter, "occupant_counts": stats, "correlations": corr_report,
            "molecule_id": molecule_id, "is_void": is_void, "unit_lattice": A}
    return structure, info


def clash_report(structure, info, threshold: float, log) -> dict:
    """Shortest distances between atoms that are not part of the same molecule (periodic)."""
    real = ~info["is_void"]
    idx = np.where(real)[0]
    if len(idx) < 2:
        return {"n_close_pairs": 0}
    A = structure.lattice.matrix
    f = structure.frac[idx] % 1.0
    mol = info["molecule_id"][idx]
    # cell list in fractional space
    lengths = np.linalg.norm(A, axis=1)
    nb = np.maximum(1, np.floor(lengths / max(threshold, 0.5)).astype(int))
    nb = np.minimum(nb, 60)
    b = np.floor(f * nb).astype(int) % nb
    key = (b[:, 0] * nb[1] + b[:, 1]) * nb[2] + b[:, 2]
    order = np.argsort(key)
    start = np.searchsorted(key[order], np.arange(nb.prod()))
    end = np.searchsorted(key[order], np.arange(nb.prod()), side="right")
    close, dmin = [], np.inf
    offsets = [(i, j, k) for i in (-1, 0, 1) for j in (-1, 0, 1) for k in (-1, 0, 1)]
    for p in range(len(idx)):
        for off in offsets:
            bb = (b[p] + off) % nb
            kk = (bb[0] * nb[1] + bb[1]) * nb[2] + bb[2]
            cand = order[start[kk]:end[kk]]
            cand = cand[cand > p]
            if not len(cand):
                continue
            df = f[cand] - f[p]
            df -= np.round(df)
            d = np.linalg.norm(df @ A, axis=1)
            other = (mol[cand] != mol[p]) | (mol[p] < 0)
            d = d[other]
            if len(d):
                dmin = min(dmin, float(d.min()))
                for q in cand[other][d < threshold]:
                    close.append((int(idx[p]), int(idx[q])))
    close = sorted(set(close))
    if close:
        log(f"  WARNING: {len(close)} atom pairs from different molecules/sites closer than {threshold} Å "
            f"(shortest {dmin:.3f} Å). Check molecule sizes, orientations and site positions.")
    else:
        log(f"  no contacts between different molecules/sites below {threshold} Å")
    return {"threshold": threshold, "n_close_pairs": len(close), "shortest": dmin, "examples": close[:20]}


# ---------------------------------------------------------------------------------------------
# DISCUS Monte Carlo (atom-only models)
# ---------------------------------------------------------------------------------------------
def build_mc_config(mc: dict, seed8):
    from discuspdf.mc import (MCConfig, Neighborhood, Vector, OccupationalTarget, DisplacementTarget,
                              SpringTarget, LennardJonesTarget, Swap, SwapDisplacement, Shift)
    nbs = []
    for nbd in mc["neighborhoods"]:
        vecs = tuple(Vector(int(v["origin"]), int(v["target"]), tuple(int(x) for x in v["t"])) for v in nbd["vectors"])
        nbs.append(Neighborhood(vecs, symmetric=bool(nbd.get("symmetric", True))))
    targets = []
    for t in mc["targets"]:
        kind = t["type"]
        common = dict(neighborhood=int(t["neighborhood"]), a=t["a"], b=t["b"])
        val = {"correlation": float(t["value"])} if t.get("mode", "correlation") == "correlation" \
            else {"energy": float(t["value"])}
        if kind == "occupational":
            targets.append(OccupationalTarget(**common, **val))
        elif kind == "displacement":
            targets.append(DisplacementTarget(**common, direction=tuple(float(x) for x in t["direction"]), **val))
        elif kind == "spring":
            targets.append(SpringTarget(**common, distance=float(t["distance"]), k=float(t["k"])))
        elif kind == "lennard_jones":
            targets.append(LennardJonesTarget(**common, distance=float(t["distance"]), depth=float(t["depth"])))
        else:
            raise ValueError(f"unknown MC target {kind!r}")
    moves = []
    mv = mc.get("moves", {})
    if mv.get("swap", 0) > 0:
        moves.append(Swap(probability=float(mv["swap"]), pairing=mv.get("pairing", "all")))
    if mv.get("swap_displacement", 0) > 0:
        moves.append(SwapDisplacement(probability=float(mv["swap_displacement"]), pairing=mv.get("pairing", "all")))
    if mv.get("shift", 0) > 0:
        moves.append(Shift(sigma={k: float(v) for k, v in mv.get("shift_sigma", {}).items()},
                           probability=float(mv["shift"])))
    from discuspdf import Seed
    return MCConfig(tuple(nbs), tuple(targets), tuple(moves), Seed(tuple(seed8)),
                    moves_per_atom=float(mc.get("moves_per_atom", 10.0)),
                    feedback_per_atom=float(mc.get("feedback_per_atom", 1.0)),
                    temperature=float(mc.get("temperature", 1.0)))


# ---------------------------------------------------------------------------------------------
# outputs of the structure
# ---------------------------------------------------------------------------------------------
def write_xyz(path: Path, structure, keep) -> None:
    cart = structure.cartesian[keep]
    sp = structure.species[keep]
    A = structure.lattice.matrix
    lat = " ".join(f"{x:.6f}" for x in A.ravel())
    lines = [str(len(sp)), f'Lattice="{lat}" Properties=species:S:1:pos:R:3 pbc="T T T"']
    lines += [f"{s} {x:.6f} {y:.6f} {z:.6f}" for s, (x, y, z) in zip(sp, cart)]
    path.write_text("\n".join(lines) + "\n", encoding="ascii")


def write_supercell(path: Path, structure, title: str, log) -> None:
    """write_stru with its read-back check; if the check refuses the file because molecule atoms lie
    more than half a cell from their slot's usual position (different orientations), the same text
    from format_stru is written without the check. DISCUS reads it either way."""
    from discuspdf import write_stru, format_stru, DiscusFormatError
    title = " ".join(title.split())[:60] or "model"
    try:
        write_stru(path, structure, title=title, overwrite=True)
    except (DiscusFormatError, ValueError) as exc:
        path.write_text(format_stru(structure, title=title), encoding="ascii", newline="\n")
        log(f"  note: discuspdf's read-back order check does not accept this file ({exc}); written "
            "without it. Atoms are listed cell by cell; only LOTS rely on that order.")


def seed8_from(rng) -> tuple:
    return tuple(int(x) for x in rng.integers(1, 99999, size=8))


# ---------------------------------------------------------------------------------------------
# DISCUS calculations
# ---------------------------------------------------------------------------------------------
def fourier_config(cfg: dict, calc3: dict, aver: float, outfile: str, seed8, lots_ok: bool):
    from discuspdf import Lattice, ReciprocalGrid, FourierConfig, Lots, Seed
    cell = cfg["cell"]
    lat = Lattice.from_parameters(cell["a"], cell["b"], cell["c"], cell["alpha"], cell["beta"], cell["gamma"])
    steps = [float(x) for x in calc3["steps"]]
    hmax = [float(x) for x in calc3["hmax"]]
    shape = tuple(2 * int(round(h / s)) + 1 for h, s in zip(hmax, steps))
    grid = ReciprocalGrid.centered(lat, shape, steps)
    lots = None
    if lots_ok and calc3.get("lots", {}).get("enabled"):
        L = calc3["lots"]
        lots = Lots(L.get("shape", "box"), tuple(int(x) for x in L["size"]),
                    "all" if str(L.get("count", "all")) == "all" else int(L["count"]), bool(L.get("periodic", True)))
    # an explicit 8-value seed is always written: needed for 0 < aver < 100 and random lots, harmless otherwise
    # radiation / wavelength need discus-python with FourierConfig(radiation=…) (PR #62); the defaults are
    # left out of the call so X-ray Mo Kα1 runs still work with an older discuspdf.
    extra = {}
    radiation = calc3.get("radiation") or "xray"
    wavelength = fourier_wavelength(calc3.get("wavelength"))
    if radiation != "xray":
        extra["radiation"] = radiation
    if wavelength != "moa1":
        extra["wavelength"] = wavelength
    try:
        return FourierConfig(grid, outputs=(("int", outfile),), aver_percent=aver, lots=lots,
                             seed=Seed(tuple(seed8)),
                             temperature="use" if cfg.get("calc", {}).get("debye_waller") else "ignore",
                             symmetry=calc3.get("symmetry") or None, **extra)
    except (TypeError, ValueError) as e:
        if "radiation" in str(e) or "only these were verified" in str(e):
            raise SystemExit("This discuspdf has no FourierConfig(radiation=…); update discus-python "
                             "(pip install -U \"discuspdf[data] @ git+https://github.com/jmsweng/discus-python\")") from e
        raise


def fourier_wavelength(w):
    """The page's λ field: a DISCUS symbol ('moa1', 'cua1', …) or a number in Å; empty means 'moa1'."""
    s = str(w if w is not None else "").strip()
    if not s:
        return "moa1"
    try:
        return float(s)
    except ValueError:
        return s.lower()


def scat_lines(cfg: dict, species, radiation: str, log=None) -> list[str]:
    """DISCUS `scat` commands (fourier menu) for atom names with a scattering length of their own (isotopes):
    `scat NAME, 0,0,0,0,0,0,0,0, b` sets the X-ray-style coefficients to zero and the constant term to b, which is
    all DISCUS uses for neutrons (fourier_sup.f90 `form`). Only for neutron runs; X-rays see the element."""
    if radiation != "neutron":
        return []
    custom = {str(k).upper(): float(v) for k, v in (cfg.get("scattering") or {}).items()}
    names = sorted({str(s).strip().upper() for s in species} - {VOID})
    out = [f"  scat {nm}, 0,0,0,0,0,0,0,0, {custom[nm]:.8g}" for nm in names if nm in custom]
    if log and out:
        log(f"  neutron scattering lengths of their own: " + ", ".join(f"{nm} {custom[nm]:g} fm" for nm in names if nm in custom))
    return out


def stage_fourier_run(runner, config, source, stru_path: Path, title: str, extra: list[str]):
    """prepare_fourier_run with extra commands placed in the fourier menu, just before `show` / `run`."""
    import tempfile
    from discuspdf import prepare_fourier_run
    if not extra:
        return prepare_fourier_run(runner, config, source, stru_path, title=title)
    text = config.render(source, title=title)
    marker = "\n  show\n  run\nexit\n"
    if text.count(marker) != 1:
        raise RuntimeError("could not place the scat commands in the generated Fourier macro")
    text = text.replace(marker, "\n" + "\n".join(extra) + marker)
    raw = stru_path.read_bytes()
    with tempfile.TemporaryDirectory() as tmp:
        macro = Path(tmp) / "run.mac"
        macro.write_bytes(text.encode("ascii"))
        staged = Path(tmp) / source.file
        staged.write_bytes(raw.replace(b"\r\n", b"\n"))
        cfgp = Path(tmp) / "fourier_config.json"
        cfgp.write_text(json.dumps({**config.to_dict(), "structure": {
            "kind": source.kind, "file": source.file, "crystal_cells": source.crystal_cells,
            "staged_with_lf": raw != staged.read_bytes()}, "scat_commands": extra}, indent=1) + "\n", encoding="utf-8")
        return runner.prepare(macro, assets=(staged, cfgp))


def run_fourier(cfg, out: Path, stru_path: Path, n, launcher, seed8, args, log, *, aver, name, lots_ok=True,
                species=()):
    from discuspdf import Diffuse3DRunner, StructureSource
    calc3 = cfg["calc"]["fourier"]
    outfile = f"{name}.h5"
    fc = fourier_config(cfg, calc3, aver, outfile, seed8, lots_ok)
    runner = Diffuse3DRunner(out / "runs_3d", launcher=launcher, output_filename=outfile,
                             timeout_seconds=int(cfg["calc"].get("timeout_s", 86400)))
    src = StructureSource.stru(stru_path.name, crystal_cells=tuple(n))
    extra = scat_lines(cfg, species, calc3.get("radiation") or "xray", log)
    run = stage_fourier_run(runner, fc, src, stru_path, f"{cfg.get('title', 'model')} {name}", extra)
    log(f"  staged {name}: grid {fc.grid.shape}, set aver {aver:g} → {run.directory}")
    if args.dry_run:
        return None
    runner.execute(run, native_nexus=True)
    log(f"  DISCUS finished {name}")
    return run.load_scattering_volume()


def save_slices(vol, title: str, png: Path, log) -> None:
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    from discuspdf import plot_slice
    fig, axes = plt.subplots(1, 3, figsize=(15, 4.6))
    for ax_i, (axis, name) in enumerate([(2, "l = 0 / w = 0"), (1, "k = 0 / v = 0"), (0, "h = 0 / u = 0")]):
        plot_slice(vol, axis=axis, ax=axes[ax_i], title=f"{title}: {name}")
    fig.tight_layout()
    fig.savefig(png, dpi=130)
    plt.close(fig)
    log(f"  wrote {png.name}")


def run_powder_pdf(cfg, out: Path, stru_path: Path, launcher, args, log, species=()):
    """1D PDF from the disordered supercell. Uses discuspdf's verified powder→PDF macro
    (render_pdf_macro) with `read stru <supercell>` instead of `read cell <unit cell>`."""
    import shutil
    from discuspdf import PDFConfig, render_pdf_macro, read_pdf, QmaxLimitWarning
    p = cfg["calc"]["pdf"]
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter("always", QmaxLimitWarning)
        pc = PDFConfig(structure="model.cll", supercell=(1, 1, 1), rmax=float(p["rmax"]), dr=float(p["dr"]),
                       qmax=float(p["qmax"]), qsig=float(p.get("qsig", 0.0)), radiation=p.get("radiation", "xray"),
                       qmin=float(p.get("qmin", 0.5)), dq=float(p.get("dq", 0.01)),
                       wavelength=float(p["wavelength"]) if str(p.get("wavelength") or "").strip() else None)
        for warning in w:
            log(f"  WARNING: {warning.message}")
    macro = render_pdf_macro(pc).replace("cell model.cll,1,1,1", f"stru {stru_path.name}")
    if f"stru {stru_path.name}" not in macro:
        raise RuntimeError("could not adapt the PDF macro to read the supercell")
    extra = scat_lines(cfg, species, p.get("radiation", "xray"), log)
    if extra:   # custom scattering lengths are set in the fourier menu and kept for the powder run
        if macro.count("\npowder\n") != 1:
            raise RuntimeError("could not place the scat commands in the PDF macro")
        macro = macro.replace("\npowder\n", "\nfourier\n" + "\n".join(extra) + "\nexit\npowder\n")
    d = out / "runs_pdf" / datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    d.mkdir(parents=True, exist_ok=True)
    shutil.copy2(stru_path, d / stru_path.name)
    (d / "run.mac").write_text(macro, encoding="ascii", newline="\n")
    (d / "pdf_config.json").write_text(json.dumps(p, indent=1), encoding="utf-8")
    log(f"  staged 1D PDF → {d}")
    if args.dry_run:
        return None
    env = os.environ.copy()
    env.pop("DISPLAY", None)
    env["PGPLOT"] = "none"
    proc = subprocess.run([*launcher, "run.mac"], cwd=d, input="exit\n", text=True, capture_output=True,
                          timeout=int(cfg["calc"].get("timeout_s", 86400)), env=env, check=False)
    (d / "run.log").write_text(proc.stdout + "\n--- STDERR ---\n" + proc.stderr, encoding="utf-8")
    import re
    err = re.search(r"(?im)\b(?:unknown command|fatal error|segmentation fault|error\s*:)", proc.stdout + proc.stderr)
    if proc.returncode != 0 or err or not (d / "result.pdf").is_file():
        raise RuntimeError(f"DISCUS powder/PDF run failed; see {d / 'run.log'}")
    r, g = read_pdf(d / "result.pdf")
    return r, g


def numpy_preview(cfg, structure, info, out: Path, log, plane=None):
    """Direct-sum diffuse intensity in one reciprocal plane, f = Z (no Q dependence, no DW):
    I_diff = |Σ_atoms f e^{2πi h·x}|² − |Σ_cells e^{2πi h·R} ⟨F_cell⟩|², per unit cell. Independent of DISCUS."""
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    plane = plane or cfg.get("calc", {}).get("preview", {"u": [1, 0, 0], "v": [0, 1, 0], "range": 6})
    u, v, R = np.array(plane["u"], float), np.array(plane["v"], float), float(plane["range"])
    o = np.array(plane.get("origin") or [0, 0, 0], float)      # plane offset, e.g. (0, 0, 0.5) for hk½
    n = np.array(structure.supercell)
    keep = ~info["is_void"]
    x = structure.frac[keep] * n                       # unit-cell fractions
    ci = structure.cell_index[keep]
    f = np.array([_z(s) for s in structure.species[keep]], float)
    loc = x - ci                                       # coordinates relative to the cell origin
    ncell = int(np.prod(n))
    cid = (ci[:, 2] * n[1] + ci[:, 1]) * n[0] + ci[:, 0]
    origins = np.array([(i % n[0], (i // n[0]) % n[1], i // (n[0] * n[1])) for i in range(ncell)], float)
    step = 1.0 / float(max(n))                         # commensurate with the supercell: no size ripples
    t = np.arange(-round(R / step), round(R / step) + 1) * step
    npts = len(t)
    I = np.zeros((npts, npts))
    for a, ta in enumerate(t):
        H = o[None, :] + ta * u[None, :] + t[:, None] * v[None, :]   # (npts, 3)
        ph = np.exp(2j * np.pi * (loc @ H.T)) * f[:, None]      # (atoms, npts)
        Fc = np.zeros((ncell, npts), complex)
        np.add.at(Fc, cid, ph)
        lat = np.exp(2j * np.pi * (origins @ H.T))              # (cells, npts)
        F = (lat * Fc).sum(axis=0)
        Fav = (lat * Fc.mean(axis=0)[None, :]).sum(axis=0)
        I[a] = (np.abs(F) ** 2 - np.abs(Fav) ** 2) / ncell
    np.savez(out / "numpy_preview_plane.npz", t=t, u=u, v=v, origin=o, intensity=I)
    # true geometry: grid points at t_a·u* + t_b·v* in an orthonormal basis of the plane (Å⁻¹, 2π convention)
    B = 2 * np.pi * np.linalg.inv(info["unit_lattice"]).T
    gu, gv = u @ B, v @ B
    e1 = gu / np.linalg.norm(gu)
    e2 = gv - (gv @ e1) * e1
    e2 /= np.linalg.norm(e2)
    TA, TB = np.meshgrid(t, t, indexing="ij")
    X = TA * (gu @ e1) + TB * (gv @ e1)
    Y = TA * (gu @ e2) + TB * (gv @ e2)
    fig, ax = plt.subplots(figsize=(6, 5.2))
    vmax = np.percentile(np.abs(I), 99.5) or 1.0
    im = ax.pcolormesh(X, Y, I, shading="nearest", cmap="magma", vmin=0, vmax=vmax)
    ax.set_aspect("equal")
    lab = lambda w: "[" + " ".join(f"{x:g}" for x in w) + "]"
    ax.set_xlabel(f"Q along u = {lab(u)} (Å⁻¹)")
    ax.set_ylabel(f"Q in the plane, normal to u (Å⁻¹); v = {lab(v)}")
    ax.set_title("numpy preview: diffuse intensity (f = Z)" + (f", offset {lab(o)}" if np.any(o) else ""))
    fig.colorbar(im, ax=ax)
    fig.tight_layout()
    fig.savefig(out / "numpy_preview_plane.png", dpi=130)
    plt.close(fig)
    log("  wrote numpy_preview_plane.png (approximate: f = Z; true plane geometry)")


# ---------------------------------------------------------------------------------------------
# main
# ---------------------------------------------------------------------------------------------
def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--config", help="read the model from a JSON file instead of the embedded one")
    ap.add_argument("--out", help="output directory (default: from the model)")
    ap.add_argument("--seed", type=int, help="override the model's random seed")
    ap.add_argument("--launcher", help='command that runs a DISCUS macro, e.g. "discus_suite -noautorun -macro"')
    ap.add_argument("--dry-run", action="store_true", help="build and stage everything; do not start DISCUS")
    ap.add_argument("--structure-only", action="store_true", help="stop after writing the structure")
    ap.add_argument("--numpy-preview", action="store_true", help="numpy diffuse plane (no DISCUS needed)")
    ap.add_argument("--overwrite", action="store_true", help="allow writing into an existing output directory")
    args = ap.parse_args(argv)

    cfg = load_config(args.config)
    seed = int(args.seed if args.seed is not None else cfg.get("seed", 1))
    out = Path(args.out or cfg.get("output_dir") or "discus_model_out").resolve()
    if out.exists() and any(out.iterdir()) and not args.overwrite:
        sys.exit(f"{out} exists and is not empty; use --overwrite or --out")
    out.mkdir(parents=True, exist_ok=True)
    log_lines = []

    def log(msg):
        print(msg, flush=True)
        log_lines.append(msg)

    calc = cfg.get("calc", {})
    launcher = shlex.split(args.launcher or calc.get("launcher") or "discus_suite -noautorun -macro")
    rng_discus = np.random.default_rng([seed, 99])

    log(f"== {cfg.get('title', 'model')} (seed {seed}) ==")
    log("Building the supercell …")
    structure, info = build_structure(cfg, seed, log)
    log(f"  {structure.n_atoms} rows ({info['n_void']} VOID padding), {info['atoms_per_cell']} per cell, "
        f"supercell {tuple(int(x) for x in structure.supercell)}, {info['n_molecules']} molecules")
    clashes = clash_report(structure, info, float(cfg.get("disorder", {}).get("clash_threshold", 0.8)), log)

    # optional DISCUS Monte Carlo on atom-only models
    mc = cfg.get("mmc") or {}
    if mc.get("enabled"):
        if info["n_molecules"]:
            sys.exit("DISCUS mmc is only offered for atom-only models (molecules would be torn apart)")
        from discuspdf.mc import MCRunner
        mcc = build_mc_config(mc, seed8_from(rng_discus))
        for c in mcc.cautions():
            log(f"  mmc note: {c}")
        runner = MCRunner(out / "runs_mc", launcher=launcher, timeout_seconds=int(calc.get("timeout_s", 86400)))
        run = runner.prepare(mcc, structure, title=f"{cfg.get('title', 'model')} mmc")
        log(f"  staged DISCUS mmc → {run.directory}")
        if not args.dry_run and not args.structure_only:
            res = runner.execute(run)
            structure = res.structure
            info["is_void"] = np.asarray(structure.species, dtype=object) == VOID
            info["molecule_id"] = np.full(structure.n_atoms, -1)
            log(f"  mmc finished: {res.status}")

    stru_path = out / "supercell.stru"
    write_supercell(stru_path, structure, cfg.get("title", "model"), log)
    write_xyz(out / "supercell.xyz", structure, ~info["is_void"])
    summary = {k: v for k, v in info.items() if k not in ("molecule_id", "is_void", "unit_lattice")}
    summary.update(seed=seed, clashes=clashes, engine=ENGINE_VERSION, n_rows=int(structure.n_atoms),
                   formula=structure.select(mask=~info["is_void"]).formula if (~info["is_void"]).any() else "")
    (out / "structure_summary.json").write_text(json.dumps(summary, indent=1, default=str), encoding="utf-8")
    (out / "model.json").write_text(json.dumps(cfg, indent=1), encoding="utf-8")
    log(f"  wrote {stru_path.name}, supercell.xyz, structure_summary.json")

    if args.numpy_preview:
        numpy_preview(cfg, structure, info, out, log)
    if args.structure_only:
        (out / "run_log.txt").write_text("\n".join(log_lines) + "\n", encoding="utf-8")
        return 0

    n = tuple(int(x) for x in structure.supercell)
    seed8 = seed8_from(rng_discus)
    f3 = calc.get("fourier", {})
    custom_b = {str(k).upper() for k in (cfg.get("scattering") or {})}
    if custom_b and calc.get("debye_waller") and structure.b_iso is not None:
        names = np.char.upper(structure.species.astype(str))
        for nm in sorted(custom_b):
            if len(np.unique(structure.b_iso[names == nm])) > 1:
                log(f"  WARNING: {nm} has several B values, so DISCUS makes several atom types of that name; "
                    "`scat` sets the scattering length of the first one only. Give the atoms one B or switch Debye–Waller off.")
    if f3.get("enabled"):
        log(f"3D diffuse scattering (DISCUS fourier, {f3.get('radiation') or 'xray'}, "
            f"λ {fourier_wavelength(f3.get('wavelength'))}, Bragg subtracted) …")
        diffuse = run_fourier(cfg, out, stru_path, n, launcher, seed8, args, log, species=structure.species,
                              aver=float(f3.get("aver_percent", 100.0)), name="diffuse")
        if diffuse is not None:
            from discuspdf import SampledVolume, write_vtk
            save_volume_npz(diffuse, out / "diffuse.npz")
            save_slices(SampledVolume.from_scattering_volume(diffuse), "diffuse", out / "diffuse_slices.png", log)
            if f3.get("delta_pdf", True):
                log("3D-ΔPDF (fractional FFT of the diffuse volume) …")
                res = diffuse.delta_pdf()
                rho = SampledVolume.from_fractional_fft(res)
                np.savez_compressed(out / "delta_pdf.npz", values=res.complex_volume.real,
                                    u=res.u_axes[0], v=res.u_axes[1], w=res.u_axes[2],
                                    direct_basis=np.asarray(res.direct_basis))
                write_vtk(rho, out / "delta_pdf.vts", overwrite=True)
                save_slices(rho, "3D-ΔPDF", out / "delta_pdf_slices.png", log)
                log(f"  imaginary/real = {res.imaginary_ratio:.1e}")
        if f3.get("total"):
            log("Total 3D scattering (Bragg present) and 3D-PDF (Patterson) …")
            total = run_fourier(cfg, out, stru_path, n, launcher, seed8, args, log, aver=0.0, name="total",
                                species=structure.species,
                                lots_ok=False)
            if total is not None:
                from discuspdf import SampledVolume, write_vtk
                save_volume_npz(total, out / "total.npz")
                save_slices(SampledVolume.from_scattering_volume(total), "total", out / "total_slices.png", log)
                pat = total.delta_pdf(require_diffuse=False)
                pv = SampledVolume.from_fractional_fft(pat, quantity="patterson")
                write_vtk(pv, out / "pdf3d_patterson.vts", overwrite=True)
                save_slices(pv, "3D-PDF", out / "pdf3d_slices.png", log)

    pdf = calc.get("pdf", {})
    if pdf.get("enabled"):
        log("1D powder PDF (DISCUS powder, Debye sum over the supercell) …")
        if structure.n_atoms > 60000:
            log(f"  note: {structure.n_atoms} atoms; the Debye sum scales as N², this can take long")
        res = run_powder_pdf(cfg, out, stru_path, launcher, args, log, species=structure.species)
        if res is not None:
            import matplotlib
            matplotlib.use("Agg")
            import matplotlib.pyplot as plt
            r, g = res
            np.savetxt(out / "pdf_1d.txt", np.column_stack([r, g]), header="r(A) G(r)")
            fig, ax = plt.subplots(figsize=(8, 4))
            ax.plot(r, g, lw=1)
            ax.set_xlabel("r (Å)")
            ax.set_ylabel("G(r)")
            ax.set_title(cfg.get("title", "model"))
            fig.tight_layout()
            fig.savefig(out / "pdf_1d.png", dpi=130)
            plt.close(fig)
            log("  wrote pdf_1d.txt, pdf_1d.png")

    if args.dry_run:
        log("Dry run: DISCUS inputs are staged; run without --dry-run to execute them.")
    (out / "run_log.txt").write_text("\n".join(log_lines) + "\n", encoding="utf-8")
    log(f"Done. Results in {out}")
    return 0


def save_volume_npz(vol, path: Path) -> None:
    """Intensity with its hkl axes (r.l.u.) and the unit cell, readable with numpy alone."""
    h, k, l = vol.grid.hkl_axes()
    np.savez_compressed(path, intensity=np.asarray(vol.intensity), h=h, k=k, l=l,
                        cell=np.array(vol.grid.lattice.parameters), bragg=str(vol.bragg))


if __name__ == "__main__":
    sys.exit(main())
